if not bit32 then
    bit32={}
    function bit32.bxor(a,b)
        local r,p=0,1
        while a>0 or b>0 do
            local xa,xb=a%2,b%2
            if xa~=xb then r=r+p end
            a,b,p=(a-xa)/2,(b-xb)/2,p*2
        end
        return r
    end
end
